files.acceptance.test.js:
import test from "node:test";
import assert from "node:assert/strict";
import { toSlug } from "./slug.js";
test("held-out slug behavior", () => {
  assert.equal(toSlug("  Hello,   Wired World!!  "), "hello-wired-world");
  assert.equal(toSlug("Already---Clean"), "already-clean");
  assert.equal(toSlug("***"), "");
  assert.equal(toSlug("Lain_01"), "lain-01");
});
